<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>二级商户与渠道关系</h2><p>进件进度、商户能力和本地启停分别管理；模拟与真实关系不混用。</p></div><Button type="primary" :disabled="blocked" @click="show=true">新增关联</Button></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div class="ui-search"><label>商户<BusinessSelect v-model="targetStore" type="stores"/></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><Table class="s1-list-table" v-compact-table :columns="columns" :data="records" :loading="loading" no-data-text="没有符合条件的渠道关系"><template slot="store" slot-scope="{row}"><button class="ui-link ui-primary-name" @click="detail(row.id)">{{names[row.storeId]||'商户名称未提供'}}</button><span class="ui-meta">{{row.subMchidMasked||'二级商户号未核验'}}</span></template><template slot="mode" slot-scope="{row}"><Tag :color="row.mode==='MOCK'?'orange':'blue'">{{status(row.mode)}}</Tag><span class="ui-meta">配置 {{configs[row.configId]||'名称未提供'}}</span></template><template slot="application" slot-scope="{row}"><StatusTag :value="row.applicationState"/><span class="ui-meta">材料 v{{row.materialVersion}}</span></template><template slot="capability" slot-scope="{row}"><StatusTag :value="row.capabilityState"/><span class="ui-meta">{{status(row.lastSyncState)}}</span></template><template slot="state" slot-scope="{row}">{{row.replaced?'历史关系':row.enabled?'本地启用':'本地停用'}}<span class="ui-meta">v{{row.version}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">详情与操作</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="changePage"/><RelationForm :visible="show" :store-id="targetStore" :disabled="blocked" :busy="busy" :error="error" @dirty="dirty=true" @save="save" @cancel="cancel"/></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import BusinessSelect from './components/BusinessSelect';import StatusTag from './components/StatusTag';import RelationForm from './components/RelationForm';import {stage1Confirm} from '../confirm';export default {mixins:[page],components:{PageStatus,BusinessSelect,StatusTag,RelationForm},data:()=>({targetStore:'',show:false,names:{},configs:{},columns:[{title:'商户／二级商户',slot:'store',minWidth:230},{title:'模式／配置',slot:'mode',minWidth:170},{title:'申请进度',slot:'application',minWidth:150},{title:'能力／最近同步',slot:'capability',minWidth:160},{title:'关系启停',slot:'state',minWidth:135},{title:'操作',slot:'operations',width:135}]}),mounted(){this.initializeList(['targetStore']);this.reload();},methods:{async reload(){const value=await this.load('/submerchants',{targetStore:this.targetStore||undefined});if(!value||!value.records.length)return;const ids=[...new Set(value.records.map(r=>r.storeId))],cfg=[...new Set(value.records.map(r=>r.configId))];try{const [stores,configs]=await Promise.all([this.ui('/lookups/stores',{selected:ids.join(','),pageSize:100}),this.ui('/lookups/channel-configs',{selected:cfg.join(','),pageSize:100})]);if(this.records===value.records){this.names=Object.fromEntries(stores.records.map(r=>[r.id,r.name]));this.configs=Object.fromEntries(configs.records.map(r=>[r.id,r.name]));}}catch(e){if(this.records===value.records)this.error=e.message;}},search(){this.page=1;this.remember(['targetStore']);this.reload();},reset(){this.targetStore='';this.search();},changePage(v){this.page=v;this.remember(['targetStore']);this.reload();},async save(body){try{const value=await this.run('/submerchants',body);if(value){this.dirty=false;this.show=false;await this.reload();this.detail(value.id);}}catch(_){}},cancel(){if(this.dirty)stage1Confirm({title:'放弃未保存关联？',content:'关闭不会建立关系。',onOk:()=>{this.show=false;this.dirty=false;}});else this.show=false;}}};</script>
